def gray_code(n):
    """ Generate the Gray code sequence for `n` bits. """
    return [(i ^ (i >> 1)) for i in range(2 ** n)]

def is_graduall_sequence(seq, a, b):
    """ Check the sequence for the constraints involving a and b. """
    for i in range(len(seq) - 1):
        if {seq[i], seq[i + 1]} == {a, b}:
            return False
    if (seq[0] == a and seq[-1] == b) or (seq[0] == b and seq[-1] == a):
        return False
    return True

