def max_goal_difference(test_cases):
    results = []
    for case in test_cases:
        N = case[0]
        goals = case[1]

        if N < 2:
            results.append("UNFIT")
            continue

        min_goals = float('inf')
        max_improvement = -1

        for current_goals in goals:
            if min_goals < current_goals:
                max_improvement = max(max_improvement, current_goals - min_goals)
            min_goals = min(min_goals, current_goals)

        if max_improvement > 0:
            results.append(str(max_improvement))
        else:
            results.append("UNFIT")

    return "\n".join(results)

