def mod_pow(base, exp, mod):
    result = 1
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def count_solutions(upper, d, m, N):
    count = [0] * N
    for x in range(min(upper, N-1) + 1):
        value = mod_pow(x, d, N)
        count[value] += 1
    total_count = 0
    for v1 in range(N):
        for v2 in range(N):
            v3 = (m - v1 - v2) % N
            if 0 <= v3 < N:
                total_count += count[v1] * count[v2] * count[v3]
                total_count %= 1000000007
    return total_count

