def knight_moves(x, y, N, board, captured_pawns):
    # Possible knight moves (valid only towards right)
    moves = [(2, 1), (1, 2)]
    max_captured = captured_pawns

    for dx, dy in moves:
        new_x, new_y = x + dx, y + dy

        # Check boundaries
        if 0 <= new_x < N and 0 <= new_y < N:
            # Check if the new position has a pawn and capture it
            current_captured = captured_pawns
            if board[new_x][new_y] == 'P':
                current_captured += 1

            # Mark the current position (if a pawn was there)
            board[new_x][new_y] = '.'  # Mark captured
            # Recur to next move
            result = knight_moves(new_x, new_y, N, board, current_captured)
            max_captured = max(max_captured, result)
            # Backtrack
            if board[new_x][new_y] == '.':
                board[new_x][new_y] = 'P'  # Restore for backtracking

    # After exploring all moves, return the max captured pawns
    return max_captured

def max_pawns(n, board):
    knight_position = None

    # Find knight's position
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'K':
                knight_position = (i, j)
                break

    # Start searching for max captures
    return knight_moves(knight_position[0], knight_position[1], n, board, 0)

